# One-off seed builder (v1). Produces data/entries.json from the curated list below + scraped GitHub star counts.
# Future agents: edit data/entries.json directly; this script is kept for provenance.
import json,csv,re
stars={}
for row in csv.reader(open('scripts/ghmeta.tsv'),delimiter='\t'):
    s=row[2] if len(row)>2 else ''
    if s:
        n=float(s.replace(',','').rstrip('k'))*(1000 if s.endswith('k') else 1)
        stars[row[1].lower()]=int(n)
MCP=["any-mcp","claude-code","codex","cursor","vscode","windsurf"]
GH="https://github.com/"
E=[]
def add(slug,name,typ,cat,url,repo,tags,works,desc):
    r=repo and repo.replace(GH,'')
    E.append(dict(slug=slug,name=name,type=typ,category=cat,description=desc,url=url,repoUrl=(GH+r if r else None),
      githubStars=stars.get(r.lower()) if r else None,tags=tags,worksWith=works,addedAt="2026-10-16"))
m="mcp-server"; t="agent-tool"
ref="modelcontextprotocol/servers"
